from __future__ import annotations

from typing import Any

from orders.application.errors import CustomerNotFound
from orders.application.order_service import OrderService
from orders.controllers.http import InvalidRequest, Response, bad_request, not_found, require_positive_int
from orders.domain.orders import OrderSummary, RankedCustomer


def history_entry(summary: OrderSummary) -> dict[str, Any]:
    return {"order_id": summary.order.order_id, "status": summary.order.status,
            "total_cents": summary.total_cents}


def ranked_entry(customer: RankedCustomer) -> dict[str, Any]:
    return {"customer_id": customer.customer_id, "name": customer.name,
            "lifetime_value_cents": customer.lifetime_value_cents}


class CustomerInsightsController:
    def __init__(self, service: OrderService) -> None:
        self._service = service

    def handle_order_history(self, customer_id: str) -> Response:
        try:
            summaries = self._service.order_history(customer_id)
        except CustomerNotFound:
            return not_found("customer")
        return Response(200, {"customer_id": customer_id,
                              "orders": [history_entry(s) for s in summaries]})

    def handle_lifetime_value(self, customer_id: str) -> Response:
        try:
            value = self._service.lifetime_value(customer_id)
        except CustomerNotFound:
            return not_found("customer")
        return Response(200, {"customer_id": customer_id, "order_count": value.order_count,
                              "lifetime_value_cents": value.lifetime_value_cents})

def order(api, customer_id, *items):
    return api.orders.handle_create({"customer_id": customer_id,
                                     "items": [{"sku": s, "quantity": q} for s, q in items]})


def test_order_history_unknown_customer_is_404(shop):
    response = shop.insights.handle_order_history("nobody")
    assert response.status == 404
    assert response.body == {"error": "customer not found"}


def test_order_history_for_customer_without_orders_is_empty(shop):
    response = shop.insights.handle_order_history("c1")
    assert response.status == 200
    assert response.body == {"customer_id": "c1", "orders": []}


def test_order_history_is_newest_first_and_includes_cancelled(shop):
    first = order(shop, "c1", ("PEN", 1)).body["order_id"]
    second = order(shop, "c1", ("BOOK", 1)).body["order_id"]
    third = order(shop, "c1", ("LAMP", 1)).body["order_id"]
    shop.orders.handle_cancel(second)

    response = shop.insights.handle_order_history("c1")

    assert response.status == 200
    assert response.body == {
        "customer_id": "c1",
        "orders": [
            {"order_id": third, "status": "placed", "total_cents": 6_000},
            {"order_id": second, "status": "cancelled", "total_cents": 2_500},
            {"order_id": first, "status": "placed", "total_cents": 300},
        ],
    }


def test_order_history_only_includes_the_requested_customer(shop):
    mine = order(shop, "c1", ("PEN", 1)).body["order_id"]
    order(shop, "c2", ("PEN", 1))

    entries = shop.insights.handle_order_history("c1").body["orders"]

    assert [e["order_id"] for e in entries] == [mine]


def test_order_history_totals_match_order_summary_including_discount(shop):
    # Four books subtotal 10_000 cents, which qualifies for the discount.
    standard = order(shop, "c1", ("BOOK", 4)).body["order_id"]
    gold = order(shop, "c2", ("BOOK", 4)).body["order_id"]

    c1_entry = shop.insights.handle_order_history("c1").body["orders"][0]
    c2_entry = shop.insights.handle_order_history("c2").body["orders"][0]

    assert c1_entry["order_id"] == standard
    assert c1_entry["total_cents"] == shop.orders.handle_get(standard).body["total_cents"] == 9_000
    assert c2_entry["order_id"] == gold
    assert c2_entry["total_cents"] == shop.orders.handle_get(gold).body["total_cents"] == 8_500


def test_lifetime_value_unknown_customer_is_404(shop):
    response = shop.insights.handle_lifetime_value("nobody")
    assert response.status == 404
    assert response.body == {"error": "customer not found"}


def test_lifetime_value_for_customer_without_orders_is_zero(shop):
    response = shop.insights.handle_lifetime_value("c1")
    assert response.status == 200
    assert response.body == {"customer_id": "c1", "order_count": 0, "lifetime_value_cents": 0}


def test_lifetime_value_excludes_cancelled_orders_and_uses_discounted_totals(shop):
    order(shop, "c1", ("BOOK", 4))  # 10_000 subtotal, 10% off -> 9_000
    order(shop, "c1", ("PEN", 2))  # 600, no discount
    cancelled = order(shop, "c1", ("LAMP", 1)).body["order_id"]
    shop.orders.handle_cancel(cancelled)

    response = shop.insights.handle_lifetime_value("c1")

    assert response.status == 200
    assert response.body == {"customer_id": "c1", "order_count": 2, "lifetime_value_cents": 9_600}


def test_lifetime_value_for_gold_customer_uses_gold_discount(shop):
    order(shop, "c2", ("BOOK", 4))  # 10_000 subtotal, 15% off -> 8_500

    response = shop.insights.handle_lifetime_value("c2")

    assert response.body == {"customer_id": "c2", "order_count": 1, "lifetime_value_cents": 8_500}

"""Order placement, lookup and cancellation.

Prices come from the catalogue, stock is checked and decremented when an
order is placed, and restored when it is cancelled.
"""

from __future__ import annotations

from collections.abc import Iterable

from orders.application.errors import Conflict, CustomerNotFound, OrderNotFound, ProductNotFound
